27		}{
28			{"encoded password", "https://alice:s3cr%40t@:8443/v1", "https://***@:8443/v1", []string{"alice", "s3cr%40t", "s3cr@t"}},
29			{"plain userinfo", "http://alice:secret@:8080/base", "http://***@:8080/base", []string{"alice", "secret"}},
30			{"username only", "http://alice@:8080/base", "http://***@:8080/base", []string{"alice"}},
31			{"empty password", "http://alice:@:8080/base", "http://***@:8080/base", []string{"alice"}},
32			{"colons in password", "http://alice:s3:cr3t@:8080/base", "http://***@:8080/base", []string{"alice", "s3:cr3t"}},
33			{"multiple at signs in authority", "https://al@ice:s3cr%40t@:8443/v1", "https://***@:8443/v1", []string{"al@ice", "s3cr%40t"}},
34			{"at sign in base path is not userinfo", "https://alice:pw9@:8443/v1@x", "https://***@:8443/v1@x", []string{"alice", "pw9"}},
35			{"userinfo reduced to empty authority", "http://svc@/base", "http://***@/base", []string{"svc"}},
36		}
37		for _, tc := range cases {
38			t.Run(tc.name, func(t *testing.T) {
39				src := `{"routes":[
40				  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
41				  {"id":"admin","methods":["GET"],"pathPrefix":"/admin","upstream":"` + tc.upstream + `"}
42				]}`
43				cfg, f := ParseConfig([]byte(src))
44				if f == nil || f.Code != "invalid_config" {
45					t.Fatalf("upstream %q: got cfg=%+v f=%+v, want invalid_config", tc.upstream, cfg, f)
46				}
47				if cfg != nil {
48					t.Fatalf("a rejected config must not be returned, got %+v", cfg)
49				}
50				for _, want := range []string{"route 2", `"admin"`, "upstream", "missing a host", `"` + tc.shown + `"`} {
51					if !strings.Contains(f.Reason, want) {
52						t.Fatalf("reason = %q, want substring %q", f.Reason, want)
53					}
54				}
