82				name:     "invalid escape in userinfo",
83				upstream: "https://alice:p%4@host.internal/",
84				want:     []string{"route 1", `"api"`, "upstream", "not a valid URL", `parse "https://***@host.internal/"`, "invalid URL escape"},
85				hidden:   []string{"alice"},
86			},
87			{
88				name:     "invalid escape in host with userinfo",
89				upstream: "https://alice:secret@ho%zzst/",
90				want:     []string{"route 1", `"api"`, "upstream", "not a valid URL", `parse "https://***@ho%zzst/"`},
91				hidden:   []string{"alice", "secret"},
92			},
93		}
94		for _, tc := range cases {
95			t.Run(tc.name, func(t *testing.T) {
96				src := `{"routes":[{"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"` + tc.upstream + `"}]}`
97				cfg, f := ParseConfig([]byte(src))
98				if f == nil || f.Code != "invalid_config" {
99					t.Fatalf("upstream %q: got cfg=%+v f=%+v, want invalid_config", tc.upstream, cfg, f)
100				}
101				for _, want := range tc.want {
102					if !strings.Contains(f.Reason, want) {
103						t.Fatalf("reason = %q, want substring %q", f.Reason, want)
104					}
105				}
106				for _, leaked := range tc.hidden {
107					if strings.Contains(f.Reason, leaked) {
108						t.Fatalf("reason = %q leaks userinfo %q", f.Reason, leaked)
109					}
110				}
111			})
112		}
113	}
114	
115	// TestUpstreamWithoutUserinfoKeepsExistingDiagnostics pins that an address
116	// without userinfo is shown in full exactly as before — redaction must not
117	// rewrite diagnostics that carry no credentials.
118	func TestUpstreamWithoutUserinfoKeepsExistingDiagnostics(t *testing.T) {
119		cases := []struct {
120			name     string
121			upstream string
