145	// TestValidUserinfoUpstreamUnchanged pins that redaction only touches
146	// failure diagnostics: a legal upstream with userinfo is still accepted,
147	// the resolved upstreamURL keeps the original address byte for byte
148	// (percent escapes included) and the stored config keeps the userinfo.
149	func TestValidUserinfoUpstreamUnchanged(t *testing.T) {
150		src := `{"routes":[{"id":"r","methods":["GET"],"pathPrefix":"/","upstream":"https://alice:s3cr%40t@host.internal:8443/v1"}]}`
151		cfg := mustConfig(t, src)
