// redactURLError renders a url.Parse failure for diagnostic output with the
// address's userinfo hidden: url.Error quotes the full original address,
// credentials included, so the address is re-rendered through
// redactUpstreamUserinfo while the underlying reason (a bad port, an
// invalid escape, ...) is kept verbatim and the address is never repeated
// in its original form. Non-url errors are returned unchanged.
func redactURLError(err error) string {
	var urlErr *url.Error
	if errors.As(err, &urlErr) {
		return fmt.Sprintf("parse %q: %v", redactUpstreamUserinfo(urlErr.URL), urlErr.Err)
	}
	return err.Error()
}

input.new_string:
// redactURLError renders a url.Parse failure for diagnostic output with the
// address's userinfo hidden: url.Error quotes the full original address,
// credentials included, so the address is re-rendered through
// redactUpstreamUserinfo while the underlying reason (a bad port, an
// invalid escape, ...) is kept verbatim unless it quotes bytes sliced out
// of the userinfo itself. url.Parse's EscapeError text repeats the offending
// escape fragment — e.g. invalid URL escape "%zz" for a password "%zz" — so
// when that fragment belongs to the userinfo it is replaced by a fixed,
// fragment-free phrase; a fragment from the host or base path is kept
// exactly as before. The address is never repeated in its original form.
// Non-url errors are returned unchanged.
func redactURLError(err error) string {
	var urlErr *url.Error
	if errors.As(err, &urlErr) {
		return fmt.Sprintf("parse %q: %s", redactUpstreamUserinfo(urlErr.URL), redactURLInnerError(urlErr.URL, urlErr.Err))
	}
	return err.Error()
}

// redactURLInnerError keeps a url.Parse inner error verbatim except when it
// quotes bytes that belong to the address's own userinfo: an EscapeError
// repeats the malformed fragment verbatim, so an invalid escape in a
// username or password would re-leak the credential the redacted address
// already hid. When the fragment occurs inside the address's userinfo range
// (the bytes between "://" and the authority's last '@', per
// splitUpstream), a fixed phrase naming the component replaces it; inner
// errors from the host or base path — an invalid host escape or path escape
// included — keep their existing, fragment-bearing text, and non-escape
// errors are untouched.
func redactURLInnerError(rawURL string, inner error) string {
	var escapeErr url.EscapeError
	if errors.As(inner, &escapeErr) {
		p := splitUpstream(rawURL)
		if p.schemeEnd >= 0 {
			if k := strings.LastIndexByte(p.authority, '@'); k >= 0 && strings.Contains(p.authority[:k], string(escapeErr)) {
				return "invalid URL escape in upstream userinfo (username or password hidden)"
			}
		}
	}
	return inner.Error()
}

