		{"illegal escape in username only", "https://al%zz@host.internal/base", "https://***@host.internal/base", []string{"al%zz", "al", "%zz"}},
		{"username-only truncated escape", "http://u%4@host/base", "http://***@host/base", []string{"u%4", "%4"}},
		{"empty password then bad username", "https://%zz:@host/", "https://***@host/", []string{"%zz"}},
		{"uppercase scheme spelling", "HTTPS://alice:%zz@host/", "HTTPS://***@host/", []string{"alice", "%zz"}},
		{"http scheme", "http://alice:%zz@host/", "http://***@host/", []string{"alice", "%zz"}},
